// codeOrchStopwords filters two-letter and short common-word substrings
// that pollute ranking via the substring-contains rule. Without them, a
// search for "list links" matches every endpoint whose description
// contains "is enrolled" because "is" is two chars and the matcher
// accepts kw.contains(t) || t.contains(kw).
var codeOrchStopwords = map[string]bool{
	"a": true, "an": true, "and": true, "are": true, "as": true,
	"at": true, "be": true, "by": true, "for": true, "from": true,
	"has": true, "in": true, "is": true, "it": true, "its": true,
	"of": true, "on": true, "or": true, "that": true, "the": true,
	"this": true, "to": true, "was": true, "will": true, "with": true,
	"your": true, "you": true, "any": true, "all": true,
}

// codeOrchKeywords produces the lowercase token stream used for search
// ranking. Defined at package level so the registry initializer can call it
// inline above without pulling in a separate precompute step.
func codeOrchKeywords(resource, endpoint, summary, path string) []string {
	raw := strings.ToLower(resource + " " + endpoint + " " + summary + " " + path)
	raw = strings.Map(func(r rune) rune {
		switch r {
		case '_', '-', '/', '{', '}', '.', ',', ':', ';':
			return ' '
		}
		return r
	}, raw)
	out := make([]string, 0, 16)
	seen := map[string]bool{}
	for _, tok := range strings.Fields(raw) {
		if len(tok) < 3 || codeOrchStopwords[tok] || seen[tok] {
			continue
		}
		seen[tok] = true
		out = append(out, tok)
	}
	return out
}

func codeOrchEndpointMetadata(ep *codeOrchEndpoint) map[string]any {
	out := map[string]any{
		"endpoint_id": ep.ID,
		"method":      ep.Method,
		"path":        ep.Path,
		"summary":     ep.Summary,
	}
	// next_cursor comes back in params under this endpoint's page cursor name.
	if ep.Page.CursorParam != "" {
		out["cursor_param"] = ep.Page.CursorParam
	}
	return out
}

func findCodeOrchEndpoint(id string) *codeOrchEndpoint {
	for i := range codeOrchEndpoints {
		if codeOrchEndpoints[i].ID == id {
			return &codeOrchEndpoints[i]
		}
	}
	return nil
}

const (
	codeOrchSearchDefaultLimit = 10
	codeOrchSearchMaxLimit     = 100
)

func codeOrchSearchLimit(args map[string]any) int {
	if v, ok := args["limit"].(float64); ok && v > 0 {
		if v > float64(codeOrchSearchMaxLimit) {
			return codeOrchSearchMaxLimit
		}
		return int(v)
	}
	return codeOrchSearchDefaultLimit
}

func handleCodeOrchSearch(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	query, ok := args["query"].(string)
	if !ok || strings.TrimSpace(query) == "" {
		return mcplib.NewToolResultError("query is required"), nil
	}
	limit := codeOrchSearchLimit(args)

	terms := codeOrchKeywords("", "", query, "")
	type scored struct {
		ep    *codeOrchEndpoint
		score int
	}
	results := make([]scored, 0, len(codeOrchEndpoints))
	for i := range codeOrchEndpoints {
		ep := &codeOrchEndpoints[i]
		score := 0
		for _, t := range terms {
			for _, kw := range ep.keywords {
				if kw == t {
					score += 2
				} else if strings.Contains(kw, t) || strings.Contains(t, kw) {
					score++
				}
			}
		}
		if score > 0 {
			results = append(results, scored{ep: ep, score: score})
		}
	}
	sort.SliceStable(results, func(i, j int) bool { return results[i].score > results[j].score })
	if len(results) > limit {
		results = results[:limit]
	}

	out := make([]map[string]any, 0, len(results))
	for _, r := range results {
		item := codeOrchEndpointMetadata(r.ep)
		item["score"] = r.score
		out = append(out, item)
	}
	text, err := bound.JSON(map[string]any{"count": len(out), "results": out})
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding search results: %v", err)), nil
	}
	return mcplib.NewToolResultText(text), nil
}

func handleCodeOrchGet(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	id, ok := args["endpoint_id"].(string)
	if !ok || id == "" {
		return mcplib.NewToolResultError("endpoint_id is required (call unifi_search first)"), nil
	}
	ep := findCodeOrchEndpoint(id)
	if ep == nil {
		return mcplib.NewToolResultError(fmt.Sprintf("unknown endpoint_id %q — call unifi_search to discover valid ids", id)), nil
	}
	if ep.Method != "GET" {
		return mcplib.NewToolResultError(fmt.Sprintf("endpoint_id %q is %s, but unifi_get only permits GET endpoints", id, ep.Method)), nil
	}
	text, err := bound.JSON(codeOrchEndpointMetadata(ep))
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding endpoint metadata: %v", err)), nil
	}
	return mcplib.NewToolResultText(text), nil
}

func codeOrchBlockedByMCPReadOnly(method string) bool {
	return cliutil.IsMCPReadOnlyEnv() && !strings.EqualFold(strings.TrimSpace(method), "GET")
}

// codeOrchRefuseForReadOnlySwitch reports calls the MCP read-only env must
// reject before a client is built. Mutating GETs are writes even though the
// verb is GET. _execute also refuses every non-GET, including read-only POSTs.
func codeOrchRefuseForReadOnlySwitch(ep *codeOrchEndpoint, method string, executeTool bool) bool {
	if !cliutil.IsMCPReadOnlyEnv() {
		return false
	}
	if method == "DELETE" || ep.NeedsConfirm || ep.Mutating {
		return true
	}
	return executeTool && codeOrchBlockedByMCPReadOnly(method)
}

func handleCodeOrchRead(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	return codeOrchInvoke(ctx, req, false)
}

func handleCodeOrchExecute(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	return codeOrchInvoke(ctx, req, true)
}

func codeOrchInvoke(ctx context.Context, req mcplib.CallToolRequest, executeTool bool) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	id, ok := args["endpoint_id"].(string)
	if !ok || id == "" {
		return mcplib.NewToolResultError("endpoint_id is required (call unifi_search first)"), nil
	}

	ep := findCodeOrchEndpoint(id)
	if ep == nil {
		return mcplib.NewToolResultError(fmt.Sprintf("unknown endpoint_id %q — call unifi_search to discover valid ids", id)), nil
	}
	method := codeOrchNormalizeMethod(ep.Method)
	if codeOrchRefuseForReadOnlySwitch(ep, method, executeTool) {
		return mcplib.NewToolResultError(fmt.Sprintf("refusing %s %s while %s=1", method, id, cliutil.MCPReadOnlyEnvVar)), nil
	}

	params, _ := args["params"].(map[string]any)
	if params == nil {
		params = map[string]any{}
	}

	c, platformSession, err := newMCPClient(ctx)
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}

	if platformSession != nil {
		defer platformSession.ZeroCredentials()
	}
	if err := cli.AdoptMCPOutputSemantics(platformSession, params); err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}

	path := ep.Path
	for _, p := range ep.Positional {
		if v, ok := params[p]; ok && strings.Contains(path, "{"+p+"}") {
			path = strings.ReplaceAll(path, "{"+p+"}", mcpPathValue(v))
			delete(params, p)
		}
	}

	hdrs := make(map[string]string, len(ep.HeaderOverrides)+len(ep.HeaderParams))
	for k, v := range ep.HeaderOverrides {
		hdrs[k] = v
	}
	for _, binding := range ep.HeaderParams {
		if binding.Default != "" {
			hdrs[binding.WireName] = binding.Default
		}
		for _, key := range []string{binding.PublicName, binding.WireName} {
			if v, ok := params[key]; ok {
				hdrs[binding.WireName] = formatMCPParamValue(v)
				delete(params, key)
				break
			}
		}
	}
	if len(hdrs) == 0 {
		hdrs = nil
	}

	// An opaque MCP cursor from a bounded page resumes that page; a raw
	// upstream cursor is sent as-is and anchors any local continuation.
	mcpCursor, requestCursor := "", ""
	if method == "GET" && ep.Page.CursorParam != "" {
		// Offset- and page-numbered APIs take numbers here, so stringify before decoding.
		if v, ok := params[ep.Page.CursorParam]; ok && v != nil {
			if s := formatMCPParamValue(v); s != "" {
				if upstream, err := bound.UpstreamCursor(s); err == nil {
					mcpCursor, requestCursor = s, upstream
					if upstream == "" {
						delete(params, ep.Page.CursorParam)
					} else {
						params[ep.Page.CursorParam] = upstream
					}
				} else {
					requestCursor = s
				}
			}
		}
	}

	// Route params to their runtime slots. GET/DELETE params are query
	// strings; write methods split spec-declared query params from the
	// remaining params used as the request body below.
	query := map[string]string{}
	if method == "GET" || method == "DELETE" {
		path = codeOrchSplitQuery(path, ep.QueryParams, params)
		for k, v := range params {
			query[codeOrchWireQueryName(ep.QueryParams, k)] = formatMCPParamValue(v)
		}
	} else {
		// Route spec-declared in:query params to the query string for write
		// methods too. Without this, a query param (e.g. sendToLedger on
		// PUT /ledger/voucher/{id}) wrongly lands in the JSON body and the
		// API silently ignores it or rejects the request. The remaining
		// params stay in the map for codeOrchWriteBody (the JSON body).
		path = codeOrchSplitQuery(path, ep.QueryParams, params)
	}

	writeBody := func() any {
		if ep.BodyIsArray {
			return codeOrchArrayBody(params)
		}
		return codeOrchWriteBody(params)
	}
	// Confirm after path and query resolution so a path param or fixed query
	// selector cannot retarget a read onto a gated endpoint without confirm.
	// Only a top-level boolean true counts; the string "true" stays a preview.
	resolvedPath := path

	gated := codeOrchResolvedNeedsConfirm(ep, method, resolvedPath, query)
	if cliutil.IsMCPReadOnlyEnv() && gated {
		return mcplib.NewToolResultError(fmt.Sprintf("refusing %s %s while %s=1", method, id, cliutil.MCPReadOnlyEnvVar)), nil
	}
	if executeTool {
		if !gated {

			return mcplib.NewToolResultError(fmt.Sprintf("endpoint_id %q is read-only; call unifi_read", id)), nil

		}
		if !codeOrchConfirmAccepted(args["confirm"]) {
			previewBody := any(nil)
			if method != "GET" && method != "DELETE" {
				previewBody = writeBody()
			}

			preview := map[string]any{
				"preview":               true,
				"confirmation_required": true,
				"endpoint_id":           ep.ID,
				"method":                method,
				"path":                  resolvedPath,
				"query":                 query,
				"body":                  previewBody,
			}
			text, previewErr := bound.JSON(preview)
			if previewErr != nil {
				return mcplib.NewToolResultError(fmt.Sprintf("encoding confirmation preview: %v", previewErr)), nil
			}
			return mcplib.NewToolResultText(text), nil
		}
	} else if gated {

		return mcplib.NewToolResultError(fmt.Sprintf("resolved %s %s changes state; call unifi_execute with confirm set to boolean true", method, resolvedPath)), nil

	}
	path = resolvedPath
	var data json.RawMessage
	switch method {
	case "GET":
		if len(hdrs) > 0 {
			if ep.Mutating {
				data, err = c.GetMutatingWithHeaders(ctx, path, query, hdrs)
			} else {
				data, err = c.GetWithHeaders(ctx, path, query, hdrs)
			}
		} else {
			if ep.Mutating {
				data, err = c.GetMutating(ctx, path, query)
			} else {
				data, err = c.Get(ctx, path, query)
			}
		}
	case "DELETE":
		if len(hdrs) > 0 {
			data, _, err = c.DeleteWithParamsAndHeaders(ctx, path, query, hdrs)
		} else {
			data, _, err = c.DeleteWithParams(ctx, path, query)
		}
	case "POST":
		body := writeBody()
		if len(hdrs) > 0 {
			data, _, err = c.PostWithHeaders(ctx, path, body, hdrs)
		} else {
			data, _, err = c.Post(ctx, path, body)
		}
	case "PUT":
		body := writeBody()
		if len(hdrs) > 0 {
			data, _, err = c.PutWithHeaders(ctx, path, body, hdrs)
		} else {
			data, _, err = c.Put(ctx, path, body)
		}
	case "PATCH":
		body := writeBody()
		if len(hdrs) > 0 {
			data, _, err = c.PatchWithHeaders(ctx, path, body, hdrs)
		} else {
			data, _, err = c.Patch(ctx, path, body)
		}
	default:
		return mcplib.NewToolResultError(fmt.Sprintf("unsupported method %q", method)), nil
	}
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	var text string
	if method == "GET" && (ep.Page.CursorParam != "" || ep.Page.NextCursorPath != "") {
		text = bound.EndpointPageResponse(method, data, bound.PageOptions{
			Cursor:         mcpCursor,
			CursorParam:    ep.Page.CursorParam,
			NextCursorPath: ep.Page.NextCursorPath,
			RequestCursor:  requestCursor,
		})
	} else {
		text = bound.EndpointResponse(method, data)
	}
	if platformSession != nil {
		text = bound.WithMetadata(text, platformSession.OutputMetadata())
	}
	return mcplib.NewToolResultText(text), nil
}

// codeOrchWriteBody returns the value handed to the client layer as the
// request body for write methods (POST/PUT/PATCH). It MUST be the structured
// params map, never pre-marshaled bytes.
//
// client.do() marshals the body value exactly once. Handing it []byte makes
// json.Marshal([]byte) emit a base64-encoded JSON *string*, so the API
// receives "eyJ...==" where it expects the request object. Strict JSON APIs
// reject that as the wrong type at the body root. GET/DELETE carry no body,
// so this defect stays latent until the first write attempt.
func codeOrchWriteBody(params map[string]any) any {
	return params
}

// codeOrchArrayBody returns the request body for endpoints whose schema root
// is a bare top-level JSON array (ep.BodyIsArray). Such a body cannot be
// expressed as the params object, so the agent supplies the array under the
// conventional params key "body" (these endpoints have no flattened named
// params, so there is no collision risk). When present and array-shaped it is
// sent as the top-level array the API expects. Otherwise params is returned
// unchanged so a malformed call fails loudly at the API (HTTP 422) instead of
// silently sending the wrong shape or a partial write — financial mutations
// are never retried with body-variant guesses (broken-convenience guardrail).
func codeOrchArrayBody(params map[string]any) any {
	if v, ok := params["body"]; ok {
		if arr, ok := v.([]any); ok {
			return arr
		}
	}
	return params
}

// codeOrchSplitQuery removes spec-declared in:query params from params and
// appends them URL-encoded to the request path. The remaining
// entries stay in the map for codeOrchWriteBody (the JSON body), so a write
// method's query parameters never get buried in the body. Mutates params by
// design (deletes the consumed query keys).
func codeOrchSplitQuery(path string, queryParams []codeOrchParamBinding, params map[string]any) string {
	uv := neturl.Values{}
	for _, q := range queryParams {
		for _, key := range []string{q.PublicName, q.WireName} {
			if key == "" {
				continue
			}
			if v, ok := params[key]; ok {
				if q.QueryArray {
					path = appendMCPArrayQueryParam(path, q.WireName, v, q.QueryStyle, q.QueryExplode)
				} else {
					uv.Set(q.WireName, formatMCPParamValue(v))
				}
				delete(params, key)
				break
			}
		}
	}
	if enc := cliutil.EncodeQuery(uv); enc != "" {
		sep := "?"
		if strings.Contains(path, "?") {
			sep = "&"
		}
		path += sep + enc
	}
	return path
}

func codeOrchWireQueryName(queryParams []codeOrchParamBinding, name string) string {
	for _, q := range queryParams {
		if q.PublicName == name || q.WireName == name {
			return q.WireName
		}
	}
	return name
}

func codeOrchNormalizeMethod(method string) string {
	return strings.ToUpper(strings.TrimSpace(method))
}

func codeOrchConfirmAccepted(v any) bool {
	confirmed, ok := v.(bool)
	return ok && confirmed
}

func codeOrchPreviewPath(path string, templateVars map[string]string) string {
	if len(templateVars) == 0 || !strings.Contains(path, "{") {
		return path
	}
	names := make([]string, 0, len(templateVars))
	for name := range templateVars {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		value := templateVars[name]
		if name == "" || value == "" {
			continue
		}
		path = strings.ReplaceAll(path, "{"+name+"}", cliutil.EscapePathParam(value))
	}
	return path
}

func codeOrchResolvedNeedsConfirm(selected *codeOrchEndpoint, method, resolvedPath string, query map[string]string) bool {
	method = codeOrchNormalizeMethod(method)
	if method == "DELETE" || selected.NeedsConfirm || selected.Mutating {
		return true
	}
	effective := codeOrchEffectiveQuery(resolvedPath, query)
	resolvedBase := codeOrchPathBase(resolvedPath)
	// A literal route is the destination when a placeholder route also
	// matches. POST /reports/search stays a read even though POST
	// /reports/{id} matches the same path.
	selectedMatches := codeOrchRequestMatchesEndpoint(selected.Path, resolvedBase, effective)
	selectedSpecificity := codeOrchPatternSpecificity(selected.Path)
	for i := range codeOrchEndpoints {
		other := &codeOrchEndpoints[i]
		if other == selected {
			continue
		}
		if !other.NeedsConfirm && !other.Mutating && codeOrchNormalizeMethod(other.Method) != "DELETE" {
			continue
		}
		if codeOrchNormalizeMethod(other.Method) != method {
			continue
		}
		if !codeOrchRequestMatchesEndpoint(other.Path, resolvedBase, effective) {
			continue
		}
		if selectedMatches && selectedSpecificity > codeOrchPatternSpecificity(other.Path) {
			continue
		}
		return true
	}
	return codeOrchFixedQueryOverridden(selected.Path, effective)
}

func codeOrchPatternSpecificity(pattern string) int {
	base := strings.Trim(codeOrchPathBase(pattern), "/")
	if base == "" {
		return 0
	}
	score := 0
	for _, seg := range strings.Split(base, "/") {
		if len(seg) >= 2 && seg[0] == '{' && seg[len(seg)-1] == '}' {
			continue
		}
		score++
	}
	return score
}

func codeOrchPathBase(path string) string {
	if i := strings.Index(path, "?"); i >= 0 {
		return path[:i]
	}
	return path
}

func codeOrchEffectiveQuery(path string, query map[string]string) neturl.Values {
	vals := neturl.Values{}
	if i := strings.Index(path, "?"); i >= 0 && i+1 < len(path) {
		if parsed, err := neturl.ParseQuery(path[i+1:]); err == nil {
			for key, items := range parsed {
				for _, item := range items {
					vals.Add(key, item)
				}
			}
		}
	}
	for key, value := range query {
		vals.Add(key, value)
	}
	return vals
}

func codeOrchFixedQueryOverridden(pattern string, effective neturl.Values) bool {
	_, raw, ok := strings.Cut(pattern, "?")
	if !ok || raw == "" {
		return false
	}
	fixed, err := neturl.ParseQuery(raw)
	if err != nil {
		return false
	}
	for name, want := range fixed {
		got, exists := effective[name]
		if !exists {
			continue
		}
		for _, value := range got {
			matched := false
			for _, allowed := range want {
				if value == allowed {
					matched = true
					break
				}
			}
			if !matched {
				return true
			}
		}
	}
	return false
}

func codeOrchRequestMatchesEndpoint(pattern, resolvedBase string, effective neturl.Values) bool {
	patternBase, patternQuery, _ := strings.Cut(pattern, "?")
	if !codeOrchSegmentsMatch(patternBase, resolvedBase) {
		return false
	}
	if patternQuery == "" {
		return true
	}
	fixed, err := neturl.ParseQuery(patternQuery)
	if err != nil {
		return false
	}
	for key, want := range fixed {
		got := effective[key]
		if len(got) == 0 {
			return false
		}
		for _, value := range want {
			found := false
			for _, have := range got {
				if have == value {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
	}
	return true
}

func codeOrchSegmentsMatch(pattern, resolved string) bool {
	pattern = strings.Trim(pattern, "/")
	resolved = strings.Trim(resolved, "/")
	if pattern == "" || resolved == "" {
		return pattern == resolved
	}
	patternSegs := strings.Split(pattern, "/")
	resolvedSegs := strings.Split(resolved, "/")
	if len(patternSegs) != len(resolvedSegs) {
		return false
	}
	for i := range patternSegs {
		seg := patternSegs[i]
		if len(seg) >= 2 && seg[0] == '{' && seg[len(seg)-1] == '}' {
			if resolvedSegs[i] == "" {
				return false
			}
			continue
		}
		got := resolvedSegs[i]
		if unescaped, err := neturl.PathUnescape(got); err == nil {
			got = unescaped
		}
		if seg != got {
			return false
		}
	}
	return true
}
